function UploadBox({ file, uploading, uploaded, onPick, label = "ငွေလွှဲပုံထည့်ရန်နှိပ်ပါ" }) {
  const inputRef = useRef(null);
  return (
    <div>
      <input
        ref={inputRef}
        type="file"
        accept="image/*"
        className="hidden"
        onChange={(e) => onPick(e.target.files && e.target.files[0] ? e.target.files[0] : null)}
      />
      <button
        type="button"
        onClick={() => inputRef.current && inputRef.current.click()}
        disabled={uploading}
        className={`w-full border-2 border-dashed rounded-lg py-8 text-center text-sm transition disabled:opacity-70 ${
          uploaded
            ? "border-emerald-500 bg-emerald-50 text-emerald-700"
            : file
            ? "border-amber-400 bg-amber-50 text-amber-700"
            : "border-emerald-400 text-emerald-600"
        }`}
      >
        {uploading ? (
          <>⏳<br />ပုံတင်နေသည်...</>
        ) : uploaded ? (
          <>✅<br />ငွေလွှဲပြေစာ တင်ပြီးပါပြီ — {file?.name}</>
        ) : file ? (
          <>⚠️<br />ပုံတင်ခြင်း မအောင်မြင်ပါ — ပြန်နှိပ်ကြည့်ပါ</>
        ) : (
          <>☁️<br />{label}</>
        )}
      </button>
    </div>
  );
}

// ---------- Website login / register (Telegram Mini App skips this entirely) ----------
function AuthScreen({ onAuthSuccess }) {
  const [mode, setMode] = useState("login"); // "login" | "register"
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [username, setUsername] = useState("");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    if (busy) return;
    setError("");

    if (!email.trim() || !password) {
      setError("Email နှင့် Password ထည့်ပါ");
      return;
    }
    if (mode === "register" && password.length < 6) {
      setError("Password အနည်းဆုံး စာလုံး ၆ လုံး ရှိရပါမည်");
      return;
    }

    setBusy(true);
    try {
      const result =
        mode === "login"
          ? await api.login(email.trim(), password)
          : await api.register(email.trim(), password, username.trim());
      onAuthSuccess(result.token, result.user);
    } catch (err) {
      setError(err.message || "မအောင်မြင်ပါ — ပြန်စမ်းကြည့်ပါ");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="min-h-screen w-full bg-slate-100 flex justify-center items-center font-sans p-4">
      <div className="w-full max-w-sm bg-gradient-to-b from-[#3f3272] via-[#352a63] to-[#2d2456] rounded-2xl shadow-xl p-6">
        <div className="text-center mb-6">
          <div className="text-2xl font-bold text-white">{APP_NAME}</div>
          <div className="text-[#90CAF9] text-sm mt-1">
            {mode === "login" ? "အကောင့်ဝင်ပါ" : "အကောင့်အသစ် ဖွင့်ပါ"}
          </div>
        </div>

        <form onSubmit={handleSubmit} className="space-y-3">
          {mode === "register" && (
            <input
              type="text"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              placeholder="အမည် (optional)"
              className="w-full rounded-lg px-3 py-2 text-sm bg-white/95"
            />
          )}
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            placeholder="Email"
            autoComplete="email"
            className="w-full rounded-lg px-3 py-2 text-sm bg-white/95"
          />
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Password"
            autoComplete={mode === "login" ? "current-password" : "new-password"}
            className="w-full rounded-lg px-3 py-2 text-sm bg-white/95"
          />

          {error && <div className="text-rose-300 text-xs text-center">{error}</div>}

          <button
            type="submit"
            disabled={busy}
            className="w-full bg-emerald-500 hover:bg-emerald-400 disabled:opacity-60 text-white font-bold rounded-lg py-2.5 text-sm transition"
          >
            {busy ? "..." : mode === "login" ? "ဝင်မည်" : "အကောင့်ဖွင့်မည်"}
          </button>
        </form>

        <div className="text-center mt-4 text-xs text-[#90CAF9]">
          {mode === "login" ? (
            <>
              အကောင့် မရှိသေးဘူးလား?{" "}
              <button className="text-emerald-300 font-semibold underline" onClick={() => { setMode("register"); setError(""); }}>
                အကောင့်အသစ် ဖွင့်ရန်
              </button>
            </>
          ) : (
            <>
              အကောင့် ရှိပြီးသားလား?{" "}
              <button className="text-emerald-300 font-semibold underline" onClick={() => { setMode("login"); setError(""); }}>
                ဝင်ရန်
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

