  async function handleVerify() {
    setVerifyState("loading");
    setVerifyError("");
    setPlayerName("");

    // Telegram Stars/Premium use a username, not a numeric Game ID.
    if (selectedGameName(selectedPkg) === "Telegram") {
      try {
        await verifyTelegramUsernameFormat(gameId.replace(/^@/, ""));
        setVerifyState("ok");
      } catch (e) {
        setVerifyState("error");
        setVerifyError(e.message);
      }
      return;
    }

    // Steam wallet top-up needs the account login (username), not a
    // numeric Game ID either.
    if (selectedGameName(selectedPkg) === "Steam") {
      try {
        await verifySteamLoginFormat(gameId);
        setVerifyState("ok");
      } catch (e) {
        setVerifyState("error");
        setVerifyError(e.message);
      }
      return;
    }

    // Real nickname lookup: FazerCards' own player-ID check covers every
    // FazerCards-connected game already (ML all regions, MCGG, PUBG,
    // Racing Master, Sausage Man, Where Winds Meet, Blood Strike, Free Fire
    // TH, Honor of Kings) via routes/verify.js -> validateGamePlayerId.
    // Games/regions it doesn't cover (ML RU, Clash of Clans, Free Fire
    // Global) still get a real "does this Game ID look valid" check, just
    // without a nickname -- the backend returns { name: null } for those
    // rather than failing, so this one path works for every game.
    try {
      await verifyGameIdFormat(gameId);
      const gName = selectedGameName(selectedPkg);
      const needsServerId = !["PUBG Mobile", "Sausage Man", "Where Winds Meet", "Blood Strike", "Free Fire", "Honor of Kings", "Sky: Children of the Light", "Valorant", "League of Legends", "Call of Duty Mobile (Garena)", "Genshin Impact (Global)", "Honkai: Star Rail", "Honkai Impact 3rd", "Arena Breakout", "Delta Force", "EAFC Mobile", "Identity V", "Lords Mobile", "Stumble Guys", "State of Survival", "Blockman Go", "Growtopia", "Eggy Party", "Rainbow Six Mobile", "TFT Mobile"].includes(gName);
      if (needsServerId && (!serverId || !/^\d+$/.test(serverId))) {
        throw new Error("Server ID ပုံစံ မှားနေပါသည်");
      }
      // Genshin Impact / Honkai: Star Rail / Identity V need a hidden
      // server value sent to FazerCards even though no picker is shown --
      // see the same note in handleBuy().
      const hardcodedServerId =
        gName === "Genshin Impact (Global)" || gName === "Honkai: Star Rail"
          ? "asia"
          : gName === "Identity V"
            ? "Asia"
            : null;
      const data = await api.verifyPlayer(gameId, hardcodedServerId || (needsServerId ? serverId : undefined), gName, selectedPkg.label || selectedPkg.name);
      if (data.name) {
        setPlayerName(data.name);
      }
      setVerifyState("ok");
    } catch (e) {
      setVerifyState("error");
      setVerifyError(e.message);
    }
  }

  async function handleBuy() {
    if (!agree || verifyState !== "ok" || buying || modalUploading) return;
    if (payMethod === "transfer" && !modalScreenshotUrl) {
      showToast({ type: "error", msg: "ငွေလွှဲပြေစာ ပုံ တင်ပေးပါ" });
      return;
    }
    setBuying(true);
    try {
      const gName = selectedGameName(selectedPkg);
      // Genshin Impact / Honkai: Star Rail need a "Server" field on
      // FazerCards' side (Player ID alone isn't enough), but we don't show
      // a server picker to the customer -- everyone here is SEA/MM, so it's
      // hardcoded to "asia" rather than adding UI for it.
      const hardcodedServerId =
        gName === "Genshin Impact (Global)" || gName === "Honkai: Star Rail"
          ? "asia"
          : gName === "Identity V"
            ? "Asia"
            : null;
      const order = await api.createOrder({
        telegramId,
        game: gName,
        item: selectedPkg.label || selectedPkg.name,
        gameId: gameId || null,
        serverId: hardcodedServerId || serverId || null,
        qty: qtyNum,
        price: total,
        currency,
        payMethod,
        screenshotUrl: payMethod === "transfer" ? modalScreenshotUrl : null,
      });

      setOrders((o) => [mapOrder(order), ...o]);
      if (payMethod === "wallet") {
        if (currency === "mmk") setBalance((b) => b - total);
        if (currency === "thb") setBalanceThb((b) => b - total);
      }
      const [messageRows, unread] = await Promise.all([api.getMessages(telegramId), api.getUnreadCount(telegramId)]);
      setMessages(messageRows.map(mapMessage));
      setUnreadCount(unread.count);

      setModalOpen(false);
      setSuccessPopup(true);
    } catch (err) {
      if (err.message === "insufficient_balance") {
        showToast({ type: "error", msg: "လက်ကျန်ငွေ မလုံလောက်ပါ" });
      } else {
        showToast({ type: "error", msg: "ဝယ်ယူမှု မအောင်မြင်ပါ — ပြန်စမ်းကြည့်ပါ" });
      }
    } finally {
      setBuying(false);
    }
  }

  // Best-effort label for which game a package belongs to (used for the
  // order's "game" column) — falls back to "Unknown" if it can't tell.
  function selectedGameName(pkg) {
    if (!pkg) return "Unknown";
    if (ML_PASSES_GLOBAL.includes(pkg) || ML_BONUS_GLOBAL.includes(pkg) || ML_DIAMONDS_GLOBAL.includes(pkg) || ML_PASSES_PH.includes(pkg) || ML_BONUS_PH.includes(pkg) || ML_DIAMONDS_PH.includes(pkg) || ML_PASSES_RU.includes(pkg) || ML_DIAMONDS_RU.includes(pkg) || ML_PASSES_BR.includes(pkg) || ML_BONUS_BR.includes(pkg) || ML_DIAMONDS_BR.includes(pkg)) return "Mobile Legends";
    if (MC_PASSES_GLOBAL.includes(pkg) || MC_BONUS_GLOBAL.includes(pkg) || MC_DIAMONDS_GLOBAL.includes(pkg) || MC_PASSES_RU.includes(pkg) || MC_BONUS_RU.includes(pkg) || MC_DIAMONDS_RU.includes(pkg)) return "Magic Chess GoGo";
    if (PUBG_UC.includes(pkg) || PUBG_WOW.includes(pkg) || PUBG_SPECIAL.includes(pkg) || PUBG_PRIME.includes(pkg)) return "PUBG Mobile";
    if (NEWSTATE_NC.includes(pkg)) return "PUBG New State";
    if (RACING_SEA.includes(pkg) || RACING_LATAM.includes(pkg)) return "Racing Master";
    if (SAUSAGE_PACKAGES.includes(pkg)) return "Sausage Man";
    if (BLOODSTRIKE_PACKAGES.includes(pkg)) return "Blood Strike";
    if (WWM_ECHO.includes(pkg) || WWM_PASSES.includes(pkg)) return "Where Winds Meet";
    if (FF_GLOBAL_DIAMONDS.includes(pkg) || FF_GLOBAL_PASSES.includes(pkg) || FF_THAILAND_DIAMONDS.includes(pkg) || FF_THAILAND_PASSES.includes(pkg)) return "Free Fire";
    if ([STEAM_PACKAGES, STEAM_RUB_PACKAGES, STEAM_UAH_PACKAGES, STEAM_KZT_PACKAGES].some((arr) => arr.includes(pkg))) return "Steam";
    if (CAPCUT_PACKAGES.includes(pkg)) return "CapCut";
    if (TELEGRAM_STARS.includes(pkg) || TELEGRAM_PREMIUM.includes(pkg)) return "Telegram";
    if (HOK_TOKENS.includes(pkg) || HOK_SPECIAL.includes(pkg)) return "Honor of Kings";
    if (SKY_COTL_PACKAGES.includes(pkg)) return "Sky: Children of the Light";
    if ([VALORANT_ID_PACKAGES, VALORANT_KH_PACKAGES, VALORANT_MY_PACKAGES, VALORANT_PH_PACKAGES, VALORANT_SG_PACKAGES, VALORANT_TH_PACKAGES, VALORANT_VN_PACKAGES].some((arr) => arr.includes(pkg))) return "Valorant";
    if ([LOL_ID_PACKAGES, LOL_KH_PACKAGES, LOL_MY_PACKAGES, LOL_PH_PACKAGES, LOL_SG_PACKAGES, LOL_TH_PACKAGES, LOL_VN_PACKAGES].some((arr) => arr.includes(pkg))) return "League of Legends";
    if ([CODM_SGMY_PACKAGES, CODM_INDONESIA_PACKAGES].some((arr) => arr.includes(pkg))) return "Call of Duty Mobile (Garena)";
    if (GENSHIN_GLOBAL_PACKAGES.includes(pkg)) return "Genshin Impact (Global)";
    if ([HSR_GLOBAL_PACKAGES, HSR_US_PACKAGES].some((arr) => arr.includes(pkg))) return "Honkai: Star Rail";
    if ([HI3RD_ASIA_PACKAGES, HI3RD_ID_PACKAGES, HI3RD_KH_PACKAGES, HI3RD_MY_PACKAGES, HI3RD_PH_PACKAGES, HI3RD_SG_PACKAGES, HI3RD_TH_PACKAGES].some((arr) => arr.includes(pkg))) return "Honkai Impact 3rd";
    if (ARENA_BREAKOUT_PACKAGES.includes(pkg)) return "Arena Breakout";
    if ([DELTA_GLOBAL_PACKAGES, DELTA_INDONESIA_PACKAGES, DELTA_MY_PACKAGES].some((arr) => arr.includes(pkg))) return "Delta Force";
    if ([EAFC_ID_PACKAGES, EAFC_KH_PACKAGES, EAFC_MY_PACKAGES, EAFC_SG_PACKAGES].some((arr) => arr.includes(pkg))) return "EAFC Mobile";
    if (IDENTITY_V_PACKAGES.includes(pkg)) return "Identity V";
    if (LORDS_MOBILE_PACKAGES.includes(pkg)) return "Lords Mobile";
    if (STUMBLE_GUYS_PACKAGES.includes(pkg)) return "Stumble Guys";
    if (STATE_OF_SURVIVAL_PACKAGES.includes(pkg)) return "State of Survival";
    if (WATCHER_OF_REALMS_PACKAGES.includes(pkg)) return "Watcher of Realms";
    if (BLOCKMAN_GO_PACKAGES.includes(pkg)) return "Blockman Go";
    if (GROWTOPIA_PACKAGES.includes(pkg)) return "Growtopia";
    if (EGGY_PARTY_PACKAGES.includes(pkg)) return "Eggy Party";
    if ([R6_GLOBAL_PACKAGES, R6_ID_PACKAGES, R6_MY_PACKAGES, R6_PH_PACKAGES, R6_SG_PACKAGES, R6_TH_PACKAGES, R6_US_PACKAGES].some((arr) => arr.includes(pkg))) return "Rainbow Six Mobile";
    if ([TFT_ID_PACKAGES, TFT_MY_PACKAGES, TFT_PH_PACKAGES, TFT_SG_PACKAGES, TFT_TH_PACKAGES].some((arr) => arr.includes(pkg))) return "TFT Mobile";
    return "Unknown";
  }

  async function handleDepositSubmit() {
    if (depositing || depositUploading) return;
    if (!depositAmount) {
      showToast({ type: "error", msg: "ဖြည့်မည့်ပမာဏ ထည့်ပါ" });
      return;
    }
    if (currency === "thb" && Number(depositAmount) < 30) {
      showToast({ type: "error", msg: "အနည်းဆုံး 30 ဘတ် ဖြည့်ရပါမည်" });
      return;
    }
    if (!depositScreenshotUrl) {
      showToast({ type: "error", msg: "ငွေလွှဲပြေစာ ပုံ တင်ပေးပါ" });
      return;
    }
    setDepositing(true);
    try {
      const rec = await api.createDeposit({
        telegramId,
        amount: Number(depositAmount),
        currency,
        screenshotUrl: depositScreenshotUrl,
      });
      setDeposits((d) => [rec, ...d]);
      const [messageRows, unread] = await Promise.all([api.getMessages(telegramId), api.getUnreadCount(telegramId)]);
      setMessages(messageRows.map(mapMessage));
      setUnreadCount(unread.count);
      setDepositAmount("");
      setDepositFile(null);
      setDepositScreenshotUrl(null);
      showToast({ type: "ok", msg: "ငွေဖြည့်သွင်းမှု တင်ပြီးပါပြီ၊ admin မှ စစ်ဆေးပေးပါမည်" });
    } catch (err) {
      showToast({ type: "error", msg: "ငွေဖြည့်သွင်းမှု တင်ခြင်း မအောင်မြင်ပါ" });
    } finally {
      setDepositing(false);
    }
  }

